import { createServer } from 'node:http';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const pages = new Set(['home', 'faq', 'pricing', 'contact', 'terms', 'privacy', 'complaints']);

/** A deliberately read-only, stateless public API contract for isolated browser tests. */
export function publicReply(method, path, headers = {}) {
  const url = new URL(path, 'http://127.0.0.1:5174');
  if (method !== 'GET') return [405, { error: 'The fixture never accepts writes.' }];
  if (url.pathname === '/healthz') return [200, { fixture: 'kredit-public-api' }];
  if (headers.cookie || headers.authorization) return [400, { error: 'Public reads must omit credentials.' }];
  if (url.pathname === '/api/v1/pricing') {
    return [200, { policy_revision: 1, base_bps: 50, collection_bps: 50, min_fee_kobo: 0 }];
  }
  const page = /^\/api\/v1\/website\/([a-z]+)$/.exec(url.pathname)?.[1];
  if (page && pages.has(page)) {
    const version = url.searchParams.get('version');
    if (version === 'audit-outage') return [503, { error: 'Synthetic publication outage.' }];
    if (version === 'audit-malformed') return [200, { publication: {} }];
    if (version) return [404, { error: 'No such publication in the fixture.' }];
    // No override means use the repository's initial publication; it is not a new approval.
    return [200, { publication: null }];
  }
  // Missing mocks must fail visibly, never become invented accounts or financial success.
  return [503, { error: 'This endpoint is not implemented by the public test fixture.' }];
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  if (process.env.KREDIT_PUBLIC_API_FIXTURE !== '1' || process.env.APP_ENV?.trim().toLowerCase() === 'production') {
    throw new Error('This loopback-only fixture must be explicitly enabled in a test process.');
  }
  const server = createServer((req, res) => {
    const [status, body] = publicReply(req.method, req.url, req.headers);
    res.writeHead(status, { 'content-type': 'application/json', 'cache-control': 'no-store' });
    res.end(JSON.stringify(body));
  });
  server.listen(5174, '127.0.0.1');
  for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => server.close());
}

import { strict as assert } from 'node:assert';
import { test } from 'node:test';
import { publicReply } from './public-api.mjs';

test('public fixture supplies only known read contracts', () => {
  assert.deepEqual(publicReply('GET', '/api/v1/website/terms'), [200, { publication: null }]);
  assert.equal(publicReply('GET', '/api/v1/pricing')[1].base_bps, 50);
  assert.equal(publicReply('POST', '/api/v1/pricing')[0], 405);
  for (const path of ['/api/v1/me', '/api/v1/payments', '/api/v1/website/unknown']) {
    assert.equal(publicReply('GET', path)[0], 503);
  }
});
test('public fixture rejects credential forwarding and models publication failures', () => {
  for (const headers of [{ cookie: 'synthetic-session' }, { authorization: 'synthetic' }]) {
    assert.equal(publicReply('GET', '/api/v1/website/privacy', headers)[0], 400);
  }
  assert.equal(publicReply('GET', '/api/v1/website/terms?version=audit-outage')[0], 503);
  assert.equal(publicReply('GET', '/api/v1/website/terms?version=missing')[0], 404);
  assert.deepEqual(publicReply('GET', '/api/v1/website/terms?version=audit-malformed')[1], { publication: {} });
});

import { expect, test } from '@playwright/test';

test.describe('isolated public API contract', () => {
  test.skip(Boolean(process.env.PLAYWRIGHT_BASE_URL || process.env.API_INTERNAL_URL), 'Uses the explicitly isolated public test fixture, never a live stack.');

  test('initial legal publication and fees render without JavaScript', async ({ browser, baseURL }) => {
    const context = await browser.newContext({ javaScriptEnabled: false, baseURL });
    try {
      const page = await context.newPage();
      expect((await page.goto('/legal/privacy'))?.status()).toBe(200);
      await expect(page.getByRole('heading', { name: 'Privacy notice', exact: true })).toBeVisible();
      expect((await page.goto('/pricing'))?.status()).toBe(200);
      await expect(page.locator('.rates strong')).toHaveText(['0.5%', '0.5%']);
      await expect(page.getByLabel('Fee example')).toContainText('₦2,500.00');
    } finally { await context.close(); }
  });

  for (const [version, status] of [['audit-outage', 503], ['audit-malformed', 503], ['missing', 404]] as const) {
    test(`unverified legal publication ${version} never becomes a successful document`, async ({ page }) => {
      expect((await page.goto(`/legal/terms?version=${version}`))?.status()).toBe(status);
      await expect(page.locator('meta[name="robots"]')).toHaveAttribute('content', 'noindex,nofollow');
      await expect(page.getByRole('heading', { name: 'Terms of service', exact: true })).toHaveCount(0);
      await expect(page.getByText('KREDIT TECHNOLOGIES LIMITED', { exact: true })).toHaveCount(0);
    });
  }
});

